// Pure-JavaScript port of the parts of CPython's `textwrap` module that
// `argparse.HelpFormatter` relies on (`textwrap.wrap` / `textwrap.fill` with
// their default options).
//
// Mirrors CPython 3.11/3.12 Lib/textwrap.py:
//   expand_tabs=True, replace_whitespace=True, drop_whitespace=True,
//   break_long_words=True, break_on_hyphens=True, initial_indent='',
//   subsequent_indent='', fix_sentence_endings=False, max_lines=None.
//
// No external dependencies (ESM only).

// Python: _whitespace = '\t\n\x0b\x0c\r '
const WHITESPACE = '\t\n\v\f\r ';

// Character classes used to rebuild Python's `wordsep_re`.
const WS_CLASS = '[\\t\\n\\x0b\\x0c\\r ]'; // re.escape(_whitespace) equivalent
const NWS_CLASS = '[^\\t\\n\\x0b\\x0c\\r ]';
const WP_CLASS = '[\\w!"\'&.,?]'; // word_punct
const LT_CLASS = '[^\\d\\W]'; // letter

// Python's textwrap.TextWrapper.wordsep_re (re.VERBOSE), one capturing group
// spanning the whole pattern.  `\Z` is translated to `$` (no multiline flag).
const WORDSEP_SOURCE =
  '(' +
  WS_CLASS + '+' +
  '|(?<=' + WP_CLASS + ')-{2,}(?=\\w)' +
  '|' + NWS_CLASS + '+?(?:' +
  '-(?:(?<=' + LT_CLASS + '{2}-)|(?<=' + LT_CLASS + '-' + LT_CLASS + '-))' +
  '(?=' + LT_CLASS + '-?' + LT_CLASS + ')' +
  '|(?=' + WS_CLASS + '|$)' +
  '|(?<=' + WP_CLASS + ')(?=-{2,}\\w)' +
  '))';

const WORDSEP_RE = new RegExp(WORDSEP_SOURCE, 'g');
const WORDSEP_SIMPLE_RE = new RegExp('(' + WS_CLASS + '+)', 'g');

// str.expandtabs(tabsize) -- column resets on '\n' and '\r'.
function expandTabs(text, tabsize = 8) {
  if (text.indexOf('\t') === -1) return text;
  let out = '';
  let col = 0;
  for (const ch of text) {
    if (ch === '\t') {
      if (tabsize > 0) {
        const pad = tabsize - (col % tabsize);
        out += ' '.repeat(pad);
        col += pad;
      }
    } else {
      out += ch;
      if (ch === '\n' || ch === '\r') col = 0;
      else col += 1;
    }
  }
  return out;
}

// str.translate(unicode_whitespace_trans): every whitespace char -> ' '
function replaceWhitespace(text) {
  let out = '';
  for (const ch of text) {
    out += WHITESPACE.indexOf(ch) === -1 ? ch : ' ';
  }
  return out;
}

// Python's re.split() for a pattern made of a single capturing group that
// spans the whole match: unmatched gaps and the captured groups are both kept.
function reSplitCapturing(regex, text) {
  const rx = new RegExp(regex.source, regex.flags.includes('g') ? regex.flags : regex.flags + 'g');
  const pieces = [];
  let last = 0;
  let m;
  rx.lastIndex = 0;
  while ((m = rx.exec(text)) !== null) {
    pieces.push(text.slice(last, m.index));
    pieces.push(m[1] === undefined ? '' : m[1]);
    last = m.index + m[0].length;
    if (m[0].length === 0) rx.lastIndex += 1;
  }
  pieces.push(text.slice(last));
  return pieces;
}

function isBlank(s) {
  for (const ch of s) {
    if (WHITESPACE.indexOf(ch) === -1) return false;
  }
  return true;
}

export class TextWrapper {
  constructor(options = {}) {
    const {
      width = 70,
      initialIndent = '',
      subsequentIndent = '',
      expandTabs: doExpandTabs = true,
      replaceWhitespace: doReplaceWhitespace = true,
      fixSentenceEndings = false,
      breakLongWords = true,
      dropWhitespace = true,
      breakOnHyphens = true,
      tabsize = 8,
      maxLines = null,
      placeholder = ' [...]',
    } = options;
    this.width = width;
    this.initialIndent = initialIndent;
    this.subsequentIndent = subsequentIndent;
    this.expandTabs = doExpandTabs;
    this.replaceWhitespace = doReplaceWhitespace;
    this.fixSentenceEndings = fixSentenceEndings;
    this.breakLongWords = breakLongWords;
    this.dropWhitespace = dropWhitespace;
    this.breakOnHyphens = breakOnHyphens;
    this.tabsize = tabsize;
    this.maxLines = maxLines;
    this.placeholder = placeholder;
  }

  _mungeWhitespace(text) {
    if (this.expandTabs) text = expandTabs(text, this.tabsize);
    if (this.replaceWhitespace) text = replaceWhitespace(text);
    return text;
  }

  _split(text) {
    const regex = this.breakOnHyphens ? WORDSEP_RE : WORDSEP_SIMPLE_RE;
    return reSplitCapturing(regex, text).filter((c) => c !== '');
  }

  _handleLongWord(reversedChunks, curLine, curLen, width) {
    let spaceLeft;
    if (width < 1) spaceLeft = 1;
    else spaceLeft = width - curLen;

    if (this.breakLongWords) {
      const chunk = reversedChunks[reversedChunks.length - 1];
      let end = spaceLeft;
      if (this.breakOnHyphens && chunk.length > spaceLeft) {
        // break after the last hyphen, but only if there are non-hyphens
        // before it
        const searchable = chunk.slice(0, Math.max(spaceLeft, 0));
        const hyphen = searchable.lastIndexOf('-');
        if (hyphen > 0) {
          let anyNonHyphen = false;
          for (const c of chunk.slice(0, hyphen)) {
            if (c !== '-') {
              anyNonHyphen = true;
              break;
            }
          }
          if (anyNonHyphen) end = hyphen + 1;
        }
      }
      curLine.push(chunk.slice(0, Math.max(end, 0)));
      reversedChunks[reversedChunks.length - 1] = chunk.slice(Math.max(end, 0));
    } else if (curLine.length === 0) {
      curLine.push(reversedChunks.pop());
    }
    // else: drop the long word
  }

  _wrapChunks(chunks) {
    const lines = [];
    if (this.width <= 0) {
      throw new Error(`invalid width ${this.width} (must be > 0)`);
    }
    if (this.maxLines !== null) {
      let indent;
      if (this.maxLines > 1) indent = this.subsequentIndent;
      else indent = this.initialIndent;
      if (indent.length + this.placeholder.replace(/^[\t\n\v\f\r ]+/, '').length > this.width) {
        throw new Error('placeholder too large for max width');
      }
    }

    // reversed chunk stack: last element is the next chunk
    chunks = chunks.slice().reverse();

    while (chunks.length > 0) {
      const curLine = [];
      let curLen = 0;

      const indent = lines.length > 0 ? this.subsequentIndent : this.initialIndent;
      const width = this.width - indent.length;

      if (this.dropWhitespace && isBlank(chunks[chunks.length - 1]) && lines.length > 0) {
        chunks.pop();
      }

      while (chunks.length > 0) {
        const l = chunks[chunks.length - 1].length;
        if (curLen + l <= width) {
          curLine.push(chunks.pop());
          curLen += l;
        } else {
          break;
        }
      }

      if (chunks.length > 0 && chunks[chunks.length - 1].length > width) {
        this._handleLongWord(chunks, curLine, curLen, width);
        curLen = curLine.reduce((acc, c) => acc + c.length, 0);
      }

      if (this.dropWhitespace && curLine.length > 0 && isBlank(curLine[curLine.length - 1])) {
        curLen -= curLine[curLine.length - 1].length;
        curLine.pop();
      }

      if (curLine.length > 0) {
        if (
          this.maxLines === null ||
          lines.length + 1 < this.maxLines ||
          ((chunks.length === 0 ||
            (this.dropWhitespace &&
              chunks.length === 1 &&
              isBlank(chunks[0]))) &&
            curLen <= width)
        ) {
          lines.push(indent + curLine.join(''));
        } else {
          let done = false;
          while (curLine.length > 0) {
            if (
              !isBlank(curLine[curLine.length - 1]) &&
              curLen + this.placeholder.length <= width
            ) {
              curLine.push(this.placeholder);
              lines.push(indent + curLine.join(''));
              done = true;
              break;
            }
            curLen -= curLine[curLine.length - 1].length;
            curLine.pop();
          }
          if (!done) {
            if (lines.length > 0) {
              const prevLine = lines[lines.length - 1].replace(/[\t\n\v\f\r ]+$/, '');
              if (prevLine.length + this.placeholder.length <= this.width) {
                lines[lines.length - 1] = prevLine + this.placeholder;
                break;
              }
            }
            lines.push(indent + this.placeholder.replace(/^[\t\n\v\f\r ]+/, ''));
          }
          break;
        }
      }
    }
    return lines;
  }

  _splitChunks(text) {
    return this._split(this._mungeWhitespace(text));
  }

  wrap(text) {
    const chunks = this._splitChunks(text);
    if (this.fixSentenceEndings) this._fixSentenceEndings(chunks);
    return this._wrapChunks(chunks);
  }

  fill(text) {
    return this.wrap(text).join('\n');
  }
}

/**
 * textwrap.wrap(text, width) with argparse's (i.e. textwrap's) defaults.
 * Returns an array of output lines without trailing newlines.
 */
export function wrap(text, width = 70, options = {}) {
  return new TextWrapper({ ...options, width }).wrap(text);
}

/**
 * textwrap.fill(text, width) -- wrap() joined with newlines.
 */
export function fill(text, width = 70, options = {}) {
  return new TextWrapper({ ...options, width }).fill(text);
}

export default { wrap, fill, TextWrapper };

