_fixSentenceEndings(chunks) {
  const sentenceEnd = /[a-z][.!?]["']?$/;
  let i = 0;
  while (i < chunks.length - 1) {
    if (chunks[i + 1] === ' ' && sentenceEnd.test(chunks[i])) {
      chunks[i + 1] = '  ';
      i += 2;
    } else {
      i += 1;
    }
  }
}

_splitChunks(text) {
  return this._split(this._mungeWhitespace(text));
}

