// Pure-JavaScript port of the subset of CPython's `argparse` needed to
// reproduce, byte for byte, the behaviour of:
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--subject', type=str, required=True)
//     parser.add_argument('--user_data', type=str, required=True)
//     args = parser.parse_args()
//
// The implementation follows CPython's Lib/argparse.py closely (help
// formatting geometry, usage line wrapping, prefix-abbreviation matching,
// error messages, exit codes and the stdout/stderr split).
//
// ESM only; the sole import is the local textwrap port.

import { wrap as textwrapWrap, fill as textwrapFill } from './textwrap.mjs';

export const SUPPRESS = '==SUPPRESS==';
export const OPTIONAL = '?';
export const ZERO_OR_MORE = '*';
export const ONE_OR_MORE = '+';
export const REMAINDER = '...';
export const PARSER = 'A...';

// ---------------------------------------------------------------------------
// small helpers
// ---------------------------------------------------------------------------

function spaces(n) {
  return n > 0 ? ' '.repeat(n) : '';
}

function ljust(s, width) {
  return s.length >= width ? s : s + spaces(width - s.length);
}

// posixpath.basename()
export function basename(p) {
  if (typeof p !== 'string' || p === '') return '';
  const i = p.lastIndexOf('/');
  return i === -1 ? p : p.slice(i + 1);
}

// Python's repr() for str (used by "ignored explicit argument %r").
function pyRepr(s) {
  const str = String(s);
  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of str) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else {
      const cp = ch.codePointAt(0);
      if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
      else out += ch;
    }
  }
  return quote + out + quote;
}

// int(os.environ['COLUMNS']) semantics: optional surrounding whitespace,
// optional sign, decimal digits (underscore separators allowed).
function envInt(name) {
  const raw = process.env[name];
  if (raw === undefined) return 0;
  const s = raw.replace(/^[\s]+/, '').replace(/[\s]+$/, '');
  if (!/^[+-]?\d+(?:_\d+)*$/.test(s)) return 0;
  const n = Number.parseInt(s.replace(/_/g, ''), 10);
  return Number.isNaN(n) ? 0 : n;
}

// shutil.get_terminal_size().columns
export function terminalColumns(fallback = 80) {
  let columns = envInt('COLUMNS');
  if (columns <= 0) {
    let size = null;
    try {
      if (process.stdout && process.stdout.isTTY && typeof process.stdout.columns === 'number') {
        size = process.stdout.columns;
      }
    } catch {
      size = null;
    }
    columns = size && size > 0 ? size : fallback;
  }
  return columns;
}

// ---------------------------------------------------------------------------
// errors
// ---------------------------------------------------------------------------

export class ArgumentError extends Error {
  constructor(argument, message) {
    super(message);
    this.name = 'ArgumentError';
    this.argumentName = getActionName(argument);
    this.messageText = message;
  }

  toString() {
    if (this.argumentName === null || this.argumentName === undefined) {
      return `${this.messageText}`;
    }
    return `argument ${this.argumentName}: ${this.messageText}`;
  }
}

export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

function getActionName(argument) {
  if (argument === null || argument === undefined) return null;
  if (argument.optionStrings && argument.optionStrings.length) {
    return argument.optionStrings.join('/');
  }
  if (argument.metavar !== null && argument.metavar !== undefined && argument.metavar !== SUPPRESS) {
    return argument.metavar;
  }
  if (argument.dest !== null && argument.dest !== undefined && argument.dest !== SUPPRESS) {
    return argument.dest;
  }
  if (argument.choices) return '{' + argument.choices.join(',') + '}';
  return null;
}

// ---------------------------------------------------------------------------
// actions
// ---------------------------------------------------------------------------

class Action {
  constructor({
    optionStrings = [],
    dest = null,
    nargs = null,
    constValue = null,
    defaultValue = null,
    type = null,
    choices = null,
    required = false,
    help = null,
    metavar = null,
    action = 'store',
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.const = constValue;
    this.default = defaultValue;
    this.type = type;
    this.choices = choices;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.action = action;
  }

  formatUsage() {
    return this.optionStrings[0];
  }
}

// ---------------------------------------------------------------------------
// help formatting
// ---------------------------------------------------------------------------

class Section {
  constructor(formatter, parent, heading = null) {
    this.formatter = formatter;
    this.parent = parent;
    this.heading = heading;
    this.items = [];
  }

  formatHelp() {
    const formatter = this.formatter;
    if (this.parent !== null) formatter._indent();
    const join = (parts) => formatter._joinParts(parts);
    const itemHelp = join(this.items.map(([func, args]) => func.apply(formatter, args)));
    if (this.parent !== null) formatter._dedent();

    if (!itemHelp) return '';

    let heading = '';
    if (this.heading !== SUPPRESS && this.heading !== null && this.heading !== undefined) {
      heading = spaces(formatter._currentIndent) + `${this.heading}:` + '\n';
    }
    return join(['\n', heading, itemHelp, '\n']);
  }
}

export class HelpFormatter {
  constructor(prog, indentIncrement = 2, maxHelpPosition = 24, width = null) {
    if (width === null || width === undefined) {
      width = terminalColumns() - 2;
    }
    this._prog = prog;
    this._indentIncrement = indentIncrement;
    this._maxHelpPosition = Math.min(maxHelpPosition, Math.max(width - 20, indentIncrement * 2));
    this._width = width;

    this._currentIndent = 0;
    this._level = 0;
    this._actionMaxLength = 0;

    this._rootSection = new Section(this, null);
    this._currentSection = this._rootSection;

    this._whitespaceMatcher = /[\t\n\v\f\r ]+/g;
    this._longBreakMatcher = /\n\n\n+/g;
  }

  // -- indentation ---------------------------------------------------------
  _indent() {
    this._currentIndent += this._indentIncrement;
    this._level += 1;
  }

  _dedent() {
    this._currentIndent -= this._indentIncrement;
    if (this._currentIndent < 0) throw new Error('Indent decreased below 0.');
    this._level -= 1;
  }

  _addItem(func, args) {
    this._currentSection.items.push([func, args]);
  }

  // -- message building ----------------------------------------------------
  startSection(heading) {
    this._indent();
    const section = new Section(this, this._currentSection, heading);
    this._addItem(section.formatHelp.bind(section), []);
    this._currentSection = section;
  }

  endSection() {
    this._currentSection = this._currentSection.parent;
    this._dedent();
  }

  addText(text) {
    if (text !== SUPPRESS && text !== null && text !== undefined) {
      this._addItem(this._formatText, [text]);
    }
  }

  addUsage(usage, actions, groups, prefix = null) {
    if (usage !== SUPPRESS) {
      this._addItem(this._formatUsage, [usage, actions, groups, prefix]);
    }
  }

  addArgument(action) {
    if (action.help !== SUPPRESS) {
      const invocations = [this._formatActionInvocation(action)];
      const invocationLength = Math.max(...invocations.map((i) => i.length));
      const actionLength = invocationLength + this._currentIndent;
      this._actionMaxLength = Math.max(this._actionMaxLength, actionLength);
      this._addItem(this._formatAction, [action]);
    }
  }

  addArguments(actions) {
    for (const action of actions) this.addArgument(action);
  }

  // -- help formatting -----------------------------------------------------
  formatHelp() {
    let help = this._rootSection.formatHelp();
    if (help) {
      help = help.replace(this._longBreakMatcher, '\n\n');
      help = stripNewlines(help) + '\n';
    }
    return help;
  }

  _joinParts(partStrings) {
    return partStrings.filter((p) => p && p !== SUPPRESS).join('');
  }

  _formatUsage(usage, actions, groups, prefix) {
    if (prefix === null || prefix === undefined) prefix = 'usage: ';

    if (usage !== null && usage !== undefined) {
      usage = usage.split('%(prog)s').join(this._prog);
    } else if (actions.length === 0) {
      usage = this._prog;
    } else {
      const prog = String(this._prog);

      const optionals = [];
      const positionals = [];
      for (const action of actions) {
        if (action.optionStrings.length) optionals.push(action);
        else positionals.push(action);
      }

      const format = (acts, grps) => this._formatActionsUsage(acts, grps);
      const actionUsage = format(optionals.concat(positionals), groups);
      usage = [prog, actionUsage].filter((s) => s).join(' ');

      const textWidth = this._width - this._currentIndent;
      if (prefix.length + usage.length > textWidth) {
        const partRegexp = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
        const optUsage = format(optionals, groups);
        const posUsage = format(positionals, groups);
        const optParts = optUsage.match(partRegexp) || [];
        const posParts = posUsage.match(partRegexp) || [];

        const getLines = (parts, indent, linePrefix = null) => {
          const lines = [];
          let line = [];
          const indentLength = indent.length;
          let lineLen = linePrefix !== null ? linePrefix.length - 1 : indentLength - 1;
          for (const part of parts) {
            if (lineLen + 1 + part.length > textWidth && line.length) {
              lines.push(indent + line.join(' '));
              line = [];
              lineLen = indentLength - 1;
            }
            line.push(part);
            lineLen += part.length + 1;
          }
          if (line.length) lines.push(indent + line.join(' '));
          if (linePrefix !== null) lines[0] = lines[0].slice(indentLength);
          return lines;
        };

        let lines;
        if (prefix.length + prog.length <= 0.75 * textWidth) {
          const indent = spaces(prefix.length + prog.length + 1);
          if (optParts.length) {
            lines = getLines([prog].concat(optParts), indent, prefix);
            lines = lines.concat(getLines(posParts, indent));
          } else if (posParts.length) {
            lines = getLines([prog].concat(posParts), indent, prefix);
          } else {
            lines = [prog];
          }
        } else {
          const indent = spaces(prefix.length);
          const parts = optParts.concat(posParts);
          lines = getLines(parts, indent);
          if (lines.length > 1) {
            lines = [];
            lines = lines.concat(getLines(optParts, indent));
            lines = lines.concat(getLines(posParts, indent));
          }
          lines = [prog].concat(lines);
        }
        usage = lines.join('\n');
      }
    }

    return `${prefix}${usage}\n\n`;
  }

  _formatActionsUsage(actions, groups) {
    // (mutually exclusive groups are not used by this parser, but the
    // separator clean-up below is applied exactly like CPython does)
    const parts = [];
    for (const action of actions) {
      if (action.help === SUPPRESS) {
        parts.push(null);
      } else if (!action.optionStrings.length) {
        const def = this._getDefaultMetavarForPositional(action);
        parts.push(this._formatArgs(action, def));
      } else {
        const optionString = action.optionStrings[0];
        let part;
        if (action.nargs === 0) {
          part = action.formatUsage();
        } else {
          const def = this._getDefaultMetavarForOptional(action);
          const argsString = this._formatArgs(action, def);
          part = `${optionString} ${argsString}`;
        }
        if (!action.required) part = `[${part}]`;
        parts.push(part);
      }
    }

    let text = parts.filter((item) => item !== null).join(' ');
    text = text.replace(/([[(]) /g, '$1');
    text = text.replace(/ ([\])])/g, '$1');
    text = text.replace(/[[(] *[\])]/g, '');
    text = text.replace(/^[\t\n\v\f\r ]+|[\t\n\v\f\r ]+$/g, '');
    return text;
  }

  _formatText(text) {
    if (text.includes('%(prog)')) text = text.split('%(prog)s').join(this._prog);
    const textWidth = Math.max(this._width - this._currentIndent, 11);
    const indent = spaces(this._currentIndent);
    return this._fillText(text, textWidth, indent) + '\n\n';
  }

  _formatAction(action) {
    const helpPosition = Math.min(this._actionMaxLength + 2, this._maxHelpPosition);
    const helpWidth = Math.max(this._width - helpPosition, 11);
    const actionWidth = helpPosition - this._currentIndent - 2;
    let actionHeader = this._formatActionInvocation(action);
    let indentFirst = 0;

    if (!action.help) {
      actionHeader = spaces(this._currentIndent) + actionHeader + '\n';
    } else if (actionHeader.length <= actionWidth) {
      actionHeader = spaces(this._currentIndent) + ljust(actionHeader, actionWidth) + '  ';
      indentFirst = 0;
    } else {
      actionHeader = spaces(this._currentIndent) + actionHeader + '\n';
      indentFirst = helpPosition;
    }

    const parts = [actionHeader];

    if (action.help && action.help.trim()) {
      const helpText = this._expandHelp(action);
      if (helpText) {
        const helpLines = this._splitLines(helpText, helpWidth);
        parts.push(spaces(indentFirst) + helpLines[0] + '\n');
        for (const line of helpLines.slice(1)) {
          parts.push(spaces(helpPosition) + line + '\n');
        }
      }
    } else if (!actionHeader.endsWith('\n')) {
      parts.push('\n');
    }

    return this._joinParts(parts);
  }

  _formatActionInvocation(action) {
    if (!action.optionStrings.length) {
      const def = this._getDefaultMetavarForPositional(action);
      return this._metavarFormatter(action, def)(1)[0];
    }
    const parts = [];
    if (action.nargs === 0) {
      parts.push(...action.optionStrings);
    } else {
      const def = this._getDefaultMetavarForOptional(action);
      const argsString = this._formatArgs(action, def);
      for (const optionString of action.optionStrings) {
        parts.push(`${optionString} ${argsString}`);
      }
    }
    return parts.join(', ');
  }

  _metavarFormatter(action, defaultMetavar) {
    let result;
    if (action.metavar !== null && action.metavar !== undefined) result = action.metavar;
    else if (action.choices !== null && action.choices !== undefined) {
      result = '{' + action.choices.join(',') + '}';
    } else result = defaultMetavar;
    return (size) => (Array.isArray(result) ? result : new Array(size).fill(result));
  }

  _formatArgs(action, defaultMetavar) {
    const getMetavar = this._metavarFormatter(action, defaultMetavar);
    const nargs = action.nargs;
    if (nargs === null || nargs === undefined) return `${getMetavar(1)[0]}`;
    if (nargs === OPTIONAL) return `[${getMetavar(1)[0]}]`;
    if (nargs === ZERO_OR_MORE) {
      const m = getMetavar(2);
      return `[${m[0]} [${m[1]} ...]]`;
    }
    if (nargs === ONE_OR_MORE) {
      const m = getMetavar(2);
      return `${m[0]} [${m[1]} ...]`;
    }
    if (nargs === REMAINDER) return '...';
    if (nargs === PARSER) return `${getMetavar(1)[0]} ...`;
    if (nargs === SUPPRESS) return '';
    return getMetavar(nargs).join(' ');
  }

  _expandHelp(action) {
    return String(this._getHelpString(action));
  }

  _getHelpString(action) {
    return action.help;
  }

  _splitLines(text, width) {
    text = text.replace(this._whitespaceMatcher, ' ').trim();
    return textwrapWrap(text, width);
  }

  _fillText(text, width, indent) {
    text = text.replace(this._whitespaceMatcher, ' ').trim();
    return textwrapFill(text, width, { initialIndent: indent, subsequentIndent: indent });
  }

  _getDefaultMetavarForOptional(action) {
    return String(action.dest).toUpperCase();
  }

  _getDefaultMetavarForPositional(action) {
    return action.dest;
  }
}

function stripNewlines(s) {
  let start = 0;
  let end = s.length;
  while (start < end && s[start] === '\n') start += 1;
  while (end > start && s[end - 1] === '\n') end -= 1;
  return s.slice(start, end);
}

// ---------------------------------------------------------------------------
// the parser
// ---------------------------------------------------------------------------

export class ArgumentParser {
  constructor({
    prog = null,
    usage = null,
    description = null,
    epilog = null,
    prefixChars = '-',
    addHelp = true,
    allowAbbrev = true,
    exitOnError = true,
    formatterClass = HelpFormatter,
  } = {}) {
    this.prog = prog === null || prog === undefined ? basename(process.argv[1] || '') : prog;
    this.usage = usage;
    this.description = description;
    this.epilog = epilog;
    this.prefixChars = prefixChars;
    this.addHelpFlag = addHelp;
    this.allowAbbrev = allowAbbrev;
    this.exitOnError = exitOnError;
    this.formatterClass = formatterClass;

    this._actions = [];
    this._optionStringActions = new Map();
    this._defaults = new Map();
    this._mutuallyExclusiveGroups = [];

    const defaultPrefix = prefixChars.includes('-') ? '-' : prefixChars[0];
    this._positionalsGroup = { title: 'positional arguments', description: null, actions: [] };
    this._optionalsGroup = { title: 'options', description: null, actions: [] };
    this._actionGroups = [this._positionalsGroup, this._optionalsGroup];

    if (addHelp) {
      this._addAction(
        new Action({
          optionStrings: [defaultPrefix + 'h', defaultPrefix + defaultPrefix + 'help'],
          dest: SUPPRESS,
          defaultValue: SUPPRESS,
          nargs: 0,
          action: 'help',
          help: 'show this help message and exit',
        })
      );
    }
  }

  // -- construction --------------------------------------------------------
  /**
   * addArgument('--flag', { ... }) / addArgument(['-f', '--flag'], { ... })
   */
  addArgument(name, options = {}) {
    const {
      type = String,
      required = false,
      default: dflt = null,
      help = null,
      metavar = null,
      dest = null,
      action = 'store',
      nargs,
      const: constValue = null,
      choices = null,
    } = options;

    const names = Array.isArray(name) ? name.slice() : [name];
    const optionStrings = [];
    for (const n of names) {
      if (typeof n !== 'string' || n.length === 0 || !this.prefixChars.includes(n[0])) {
        throw new Error(`invalid option string ${pyRepr(String(n))}: must start with a character ${pyRepr(this.prefixChars)}`);
      }
      optionStrings.push(n);
    }

    // auto dest: first long option, else first option
    let realDest = dest;
    if (realDest === null || realDest === undefined) {
      let destOptionString = null;
      for (const optionString of optionStrings) {
        if (optionString.length > 1 && this.prefixChars.includes(optionString[1])) {
          destOptionString = optionString;
          break;
        }
      }
      if (destOptionString === null) destOptionString = optionStrings[0];
      let d = destOptionString;
      while (d.length && this.prefixChars.includes(d[0])) d = d.slice(1);
      if (!d) throw new Error(`dest= is required for options like ${pyRepr(optionStrings[0])}`);
      realDest = d.split('-').join('_');
    }

    let realNargs = nargs === undefined ? null : nargs;
    let realDefault = dflt;
    let realType = type;
    switch (action) {
      case 'store':
        break;
      case 'store_true':
        realNargs = 0;
        realDefault = dflt === null ? false : dflt;
        realType = null;
        break;
      case 'store_false':
        realNargs = 0;
        realDefault = dflt === null ? true : dflt;
        realType = null;
        break;
      case 'store_const':
        realNargs = 0;
        realType = null;
        break;
      case 'count':
        realNargs = 0;
        realType = null;
        break;
      case 'append':
        break;
      case 'help':
        realNargs = 0;
        realType = null;
        break;
      default:
        throw new Error(`unknown action ${pyRepr(String(action))}`);
    }

    const actionObj = new Action({
      optionStrings,
      dest: realDest,
      nargs: realNargs,
      constValue,
      defaultValue: realDefault,
      type: realType,
      choices,
      required,
      help,
      metavar,
      action,
    });
    this._addAction(actionObj);
    return actionObj;
  }

  _addAction(action) {
    for (const optionString of action.optionStrings) {
      if (this._optionStringActions.has(optionString)) {
        throw new Error(`conflicting option string: ${optionString}`);
      }
    }
    this._actions.push(action);
    for (const optionString of action.optionStrings) {
      this._optionStringActions.set(optionString, action);
    }
    if (action.optionStrings.length) this._optionalsGroup.actions.push(action);
    else this._positionalsGroup.actions.push(action);
    return action;
  }

  _getPositionalActions() {
    return this._actions.filter((a) => !a.optionStrings.length);
  }

  // -- formatting ----------------------------------------------------------
  _getFormatter() {
    return new this.formatterClass(this.prog);
  }

  formatUsage() {
    const formatter = this._getFormatter();
    formatter.addUsage(this.usage, this._actions, this._mutuallyExclusiveGroups);
    return formatter.formatHelp();
  }

  formatHelp() {
    const formatter = this._getFormatter();
    formatter.addUsage(this.usage, this._actions, this._mutuallyExclusiveGroups);
    formatter.addText(this.description);
    for (const group of this._actionGroups) {
      formatter.startSection(group.title);
      formatter.addText(group.description);
      formatter.addArguments(group.actions);
      formatter.endSection();
    }
    formatter.addText(this.epilog);
    return formatter.formatHelp();
  }

  printUsage(stream) {
    this._printMessage(this.formatUsage(), stream || process.stdout);
  }

  printHelp(stream) {
    this._printMessage(this.formatHelp(), stream || process.stdout);
  }

  _printMessage(message, stream) {
    if (message) {
      const target = stream || process.stderr;
      try {
        target.write(message);
      } catch {
        /* ignore */
      }
    }
  }

  // -- exiting -------------------------------------------------------------
  exit(status = 0, message = null) {
    if (message) this._printMessage(message, process.stderr);
    process.exit(status);
  }

  error(message) {
    this.printUsage(process.stderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  // -- parsing -------------------------------------------------------------
  parseArgs(argv = process.argv.slice(2), namespace = null) {
    const [args, argvExtras] = this.parseKnownArgs(argv, namespace);
    if (argvExtras.length) {
      this.error(`unrecognized arguments: ${argvExtras.join(' ')}`);
    }
    return args;
  }

  parseKnownArgs(argv = process.argv.slice(2), namespace = null) {
    const args = Array.from(argv);
    let ns = namespace === null || namespace === undefined ? {} : namespace;

    for (const action of this._actions) {
      if (action.dest !== SUPPRESS) {
        if (!Object.prototype.hasOwnProperty.call(ns, action.dest)) {
          if (action.default !== SUPPRESS) ns[action.dest] = action.default;
        }
      }
    }
    for (const [dest, value] of this._defaults) {
      if (!Object.prototype.hasOwnProperty.call(ns, dest)) ns[dest] = value;
    }

    let result;
    if (this.exitOnError) {
      try {
        result = this._parseKnownArgs(args, ns);
      } catch (err) {
        if (err instanceof ArgumentError) {
          this.error(err.toString());
          return [ns, []]; // unreachable (error() exits)
        }
        throw err;
      }
    } else {
      result = this._parseKnownArgs(args, ns);
    }
    return result;
  }

  _parseKnownArgs(argStrings, namespace) {
    // determine which arg strings are options and which are positionals
    const optionStringIndices = new Map();
    const argStringPatternParts = [];
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (argString === '--') {
        argStringPatternParts.push('-');
        for (let j = i + 1; j < argStrings.length; j += 1) argStringPatternParts.push('A');
        i = argStrings.length;
        break;
      }
      const optionTuple = this._parseOptional(argString);
      if (optionTuple === null) {
        argStringPatternParts.push('A');
      } else {
        optionStringIndices.set(i, optionTuple);
        argStringPatternParts.push('O');
      }
    }
    const argStringsPattern = argStringPatternParts.join('');

    const seenActions = new Set();
    const seenNonDefaultActions = new Set();
    const extras = [];

    const takeAction = (action, argumentStrings, optionString = null) => {
      seenActions.add(action);
      const argumentValues = this._getValues(action, argumentStrings);
      if (argumentValues !== action.default) seenNonDefaultActions.add(action);
      if (argumentValues !== SUPPRESS) {
        this._callAction(action, namespace, argumentValues, optionString);
      }
    };

    const consumeOptional = (startIndex) => {
      const optionTuple = optionStringIndices.get(startIndex);
      let [action, optionString, sep, explicitArg] = optionTuple;

      const actionTuples = [];
      let stop;
      for (;;) {
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this._matchArgument(action, 'A');
          const chars = this.prefixChars;
          if (argCount === 0 && optionString.length > 1 && !chars.includes(optionString[1]) && explicitArg !== '') {
            if (sep || chars.includes(explicitArg[0])) {
              throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
            }
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this._optionStringActions.has(optionString)) {
              action = this._optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (!explicitArg) {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
          }
        } else {
          const start = startIndex + 1;
          const selectedPatterns = argStringsPattern.slice(start);
          const argCount = this._matchArgument(action, selectedPatterns);
          stop = start + argCount;
          const args = argStrings.slice(start, stop);
          actionTuples.push([action, args, optionString]);
          break;
        }
      }

      for (const [act, args, optStr] of actionTuples) takeAction(act, args, optStr);
      return stop;
    };

    // this parser only supports optionals; positionals never consume anything
    const positionals = this._getPositionalActions();
    const consumePositionals = (startIndex) => {
      if (!positionals.length) return startIndex;
      throw new Error('positional arguments are not supported by this argparse port');
    };

    let startIndex = 0;
    const indices = Array.from(optionStringIndices.keys());
    const maxOptionStringIndex = indices.length ? Math.max(...indices) : -1;
    while (startIndex <= maxOptionStringIndex) {
      const candidates = indices.filter((idx) => idx >= startIndex);
      const nextOptionStringIndex = Math.min(...candidates);
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        } else {
          startIndex = positionalsEndIndex;
        }
      }
      if (startIndex !== nextOptionStringIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }
      startIndex = consumeOptional(nextOptionStringIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    // make sure all required actions were present
    const requiredActions = [];
    for (const action of this._actions) {
      if (!seenActions.has(action)) {
        if (action.required) {
          requiredActions.push(getActionName(action));
        } else if (
          action.default !== null &&
          typeof action.default === 'string' &&
          Object.prototype.hasOwnProperty.call(namespace, action.dest) &&
          namespace[action.dest] === action.default
        ) {
          namespace[action.dest] = this._getValue(action, action.default);
        }
      }
    }
    if (requiredActions.length) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }

  _matchArgument(action, argStringsPattern) {
    const nargsPattern = this._getNargsPattern(action);
    const match = new RegExp('^' + nargsPattern).exec(argStringsPattern);
    if (match === null) {
      let msg;
      if (action.nargs === null || action.nargs === undefined) msg = 'expected one argument';
      else if (action.nargs === OPTIONAL) msg = 'expected at most one argument';
      else if (action.nargs === ONE_OR_MORE) msg = 'expected at least one argument';
      else msg = `expected ${action.nargs} argument${action.nargs === 1 ? '' : 's'}`;
      throw new ArgumentError(action, msg);
    }
    return match[1].length;
  }

  _getNargsPattern(action) {
    const nargs = action.nargs;
    let nargsPattern;
    if (nargs === null || nargs === undefined) nargsPattern = '(-*A-*)';
    else if (nargs === OPTIONAL) nargsPattern = '(-*A?-*)';
    else if (nargs === ZERO_OR_MORE) nargsPattern = '(-*[A-]*)';
    else if (nargs === ONE_OR_MORE) nargsPattern = '(-*A[A-]*)';
    else if (nargs === REMAINDER) nargsPattern = '([-AO]*)';
    else if (nargs === PARSER) nargsPattern = '(-*A[-AO]*)';
    else if (nargs === SUPPRESS) nargsPattern = '(-*-*)';
    else nargsPattern = '(-*' + new Array(nargs).fill('A').join('-*') + '-*)';

    if (action.optionStrings.length) {
      nargsPattern = nargsPattern.split('-*').join('');
      nargsPattern = nargsPattern.split('-').join('');
    }
    return nargsPattern;
  }

  _parseOptional(argString) {
    if (!argString) return null;
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this._optionStringActions.has(argString)) {
      return [this._optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      if (this._optionStringActions.has(optionString)) {
        return [this._optionStringActions.get(optionString), optionString, '=', explicitArg];
      }
    }

    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const options = optionTuples.map((t) => t[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    if (/^-\d+$|^-\d*\.\d+$/.test(argString)) {
      if (!this._hasNegativeNumberOptionals()) return null;
    }

    if (argString.includes(' ')) return null;

    return [null, argString, null, null];
  }

  _hasNegativeNumberOptionals() {
    for (const action of this._actions) {
      for (const optionString of action.optionStrings) {
        if (/^-\d+$|^-\d*\.\d+$/.test(optionString)) return true;
      }
    }
    return false;
  }

  _getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;
    if (chars.includes(optionString[0]) && optionString.length > 1 && chars.includes(optionString[1])) {
      if (this.allowAbbrev) {
        const eq = optionString.indexOf('=');
        let optionPrefix;
        let explicitArg;
        let sep;
        if (eq !== -1) {
          optionPrefix = optionString.slice(0, eq);
          explicitArg = optionString.slice(eq + 1);
          sep = '=';
        } else {
          optionPrefix = optionString;
          explicitArg = null;
          sep = null;
        }
        for (const [candidate, action] of this._optionStringActions) {
          if (candidate.startsWith(optionPrefix)) {
            result.push([action, candidate, sep, explicitArg]);
          }
        }
      }
    } else if (chars.includes(optionString[0]) && optionString.length > 1 && !chars.includes(optionString[1])) {
      const optionPrefix = optionString;
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [candidate, action] of this._optionStringActions) {
        if (candidate === shortOptionPrefix) {
          result.push([action, candidate, '', shortExplicitArg]);
        } else if (candidate.startsWith(optionPrefix)) {
          result.push([action, candidate, null, null]);
        }
      }
    } else {
      this.error(`unexpected option string: ${optionString}`);
    }
    return result;
  }

  // -- value conversion ----------------------------------------------------
  _getValues(action, argStrings) {
    let strings = argStrings.slice();
    if (!action.optionStrings.length && action.nargs !== PARSER && action.nargs !== REMAINDER) {
      const idx = strings.indexOf('--');
      if (idx !== -1) strings.splice(idx, 1);
    }

    let value;
    if (
      !action.optionStrings.length &&
      (action.nargs === OPTIONAL || action.nargs === undefined || action.nargs === null) &&
      strings.length === 0
    ) {
      value = action.default;
      if (typeof value === 'string') {
        value = this._getValue(action, value);
        this._checkValue(action, value);
      }
    } else if (strings.length === 1 && (action.nargs === null || action.nargs === undefined || action.nargs === OPTIONAL)) {
      value = this._getValue(action, strings[0]);
      this._checkValue(action, value);
    } else if (action.nargs === REMAINDER) {
      value = strings.map((v) => this._getValue(action, v));
    } else if (action.nargs === PARSER) {
      value = strings.map((v) => this._getValue(action, v));
      for (const v of value.slice(1)) this._checkValue(action, v);
    } else if (action.nargs === SUPPRESS) {
      value = SUPPRESS;
    } else {
      value = strings.map((v) => this._getValue(action, v));
      for (const v of value) this._checkValue(action, v);
    }
    return value;
  }

  _getValue(action, argString) {
    const typeFunc = action.type;
    if (typeFunc === null || typeFunc === undefined || typeFunc === String) {
      return String(argString);
    }
    if (typeof typeFunc !== 'function') {
      throw new ArgumentError(action, `${pyRepr(String(typeFunc))} is not callable`);
    }
    const typeName = typeFunc.name || String(typeFunc);
    if (typeFunc === Number) {
      const v = Number(argString);
      if (Number.isNaN(v) && argString.trim().toLowerCase() !== 'nan') {
        throw new ArgumentError(action, `invalid ${typeName} value: ${pyRepr(argString)}`);
      }
      return v;
    }
    try {
      return typeFunc(argString);
    } catch (err) {
      if (err instanceof ArgumentTypeError) throw new ArgumentError(action, err.message);
      throw new ArgumentError(action, `invalid ${typeName} value: ${pyRepr(argString)}`);
