import { spawnSync } from 'node:child_process';

const BIN = '/workspace/dataset/test10_executable';
const DRIVER = '/tmp/driver.mjs';
const DRIVER_HELP = '/tmp/driver_help.mjs';

function run(cmd, argv, env) {
  const r = spawnSync(cmd[0], cmd.slice(1).concat(argv), {
    env: { ...process.env, ...env },
    encoding: 'utf8',
  });
  return { rc: r.status, out: r.stdout ?? '', err: r.stderr ?? '' };
}

function b64urlDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}

function show(s) {
  return JSON.stringify(s);
}

const cases = [
  ['no args', []],
  ['only --subject', ['--subject', 'x']],
  ['--subject after --user_data', ['--user_data', 'y', '--subject', 'x']],
  ['--subject=x --user_data=y', ['--subject=x', '--user_data=y']],
  ['--sub= (empty value)', ['--sub=', '--user_data=y']],
  ['abbrev --sub/--user', ['--sub', 'x', '--user', 'y']],
  ['abbrev --s/--u', ['--s', 'x', '--u', 'y']],
  ['abbrev --he', ['--he']],
  ['unknown --xyz alone', ['--xyz']],
  ['unknown --xyz + valid', ['--subject', 'x', '--user_data', 'y', '--xyz']],
  ['unknown --xyz before valid', ['--xyz', '--subject', 'x', '--user_data', 'y']],
  ['extra positional foo', ['--subject', 'x', '--user_data', 'y', 'foo']],
  ['bare --', ['--subject', 'x', '--user_data', 'y', '--']],
  ['--subject -abc', ['--subject', '-abc']],
  ['--subject -1', ['--subject', '-1', '--user_data', 'y']],
  ['--subject -1.5', ['--subject', '-1.5', '--user_data', 'y']],
  ["--subject ' -x'", ['--subject', ' -x', '--user_data', 'y']],
  ['--subject --user_data x', ['--subject', '--user_data', 'x']],
  ['repeated --subject', ['--subject', 'a', '--subject', 'b', '--user_data', 'y']],
  ['-h', ['-h']],
  ['--help', ['--help']],
  ['--subject a -h', ['--subject', 'a', '-h']],
  ['COLUMNS=40 --help', ['--help'], { COLUMNS: '40' }],
  ['COLUMNS=200 --help', ['--help'], { COLUMNS: '200' }],
  ['COLUMNS=60 --help', ['--help'], { COLUMNS: '60' }],
  ['COLUMNS=30 --help', ['--help'], { COLUMNS: '30' }],
  ['COLUMNS=100 --help', ['--help'], { COLUMNS: '100' }],
  // extra coverage
  ['COLUMNS=1 --help', ['--help'], { COLUMNS: '1' }],
  ['COLUMNS=11 --help', ['--help'], { COLUMNS: '11' }],
  ['COLUMNS=20 --help', ['--help'], { COLUMNS: '20' }],
  ['COLUMNS=25 --help', ['--help'], { COLUMNS: '25' }],
  ['COLUMNS=26 --help', ['--help'], { COLUMNS: '26' }],
  ['COLUMNS=50 --help', ['--help'], { COLUMNS: '50' }],
  ['COLUMNS=0 --help', ['--help'], { COLUMNS: '0' }],
  ['COLUMNS=abc --help', ['--help'], { COLUMNS: 'abc' }],
  ['COLUMNS=" 40 " --help', ['--help'], { COLUMNS: ' 40 ' }],
  ['COLUMNS=-5 --help', ['--help'], { COLUMNS: '-5' }],
  ['COLUMNS=79 --help', ['--help'], { COLUMNS: '79' }],
  ['COLUMNS=69 --help', ['--help'], { COLUMNS: '69' }],
  ['COLUMNS=70 --help', ['--help'], { COLUMNS: '70' }],
  ['COLUMNS=71 --help', ['--help'], { COLUMNS: '71' }],
