  ['-h=x', ['-h=x']],
  ['--help=x', ['--help=x']],
  ['--he=1', ['--he=1']],
  ['--=x', ['--=x']],
  ['--subject -- x', ['--subject', '--', 'x']],
  ['single dash -', ['-', '--subject', 'x', '--user_data', 'y']],
  ['empty string arg', ['', '--subject', 'x', '--user_data', 'y']],
  ['--subject (no value)', ['--subject']],
  ['-- -h after valid', ['--subject', 'x', '--user_data', 'y', '--', '-h']],
  ['unknown -z alone', ['-z']],
  ['--subject=a=b', ['--subject=a=b', '--user_data=y']],
  ['--subject==x', ['--subject==x', '--user_data', 'y']],
  ['--user_data -', ['--subject', 'x', '--user_data', '-']],
  ['--s (no value)', ['--s']],
