  if (ref.rc !== mine.rc) {
    ok = false;
    diffs.push(`rc: ref=${ref.rc} mine=${mine.rc}`);
  }
  if (ref.err !== mine.err) {
    ok = false;
    diffs.push(`stderr:\n  ref =${show(ref.err)}\n  mine=${show(mine.err)}`);
  }

  if (ref.rc === 0) {
    if (ref.out.startsWith('usage:')) {
      // help output: byte-for-byte
      if (ref.out !== mine.out) {
        ok = false;
        diffs.push(`stdout(help):\n  ref =${show(ref.out)}\n  mine=${show(mine.out)}`);
