cases = json.loads(sys.stdin.read())
out = []
for text, width in cases:
    out.append([textwrap.wrap(text, width), textwrap.fill(text, width)])
sys.stdout.write(json.dumps(out))
`;

const r = spawnSync('python3', ['-c', pyScript], {
  input: JSON.stringify(pyCases),
  encoding: 'utf8',
});
if (r.status !== 0) {
  console.error(r.stderr);
  process.exit(1);
}
const expected = JSON.parse(r.stdout);

let fails = 0;
for (let i = 0; i < pyCases.length; i += 1) {
  const [text, width] = pyCases[i];
  const [expWrap, expFill] = expected[i];
  const gotWrap = wrap(text, width);
  const gotFill = fill(text, width);
